        if (tokens.Length != 2) return false;
        actionType = tokens[0].ToLowerInvariant() switch
        {
            "quarantine" => "file.quarantine",
            "quarantine-status" => "file.quarantine_status",
            "restore" => "file.restore",
            "delete-file" => "file.delete",
            _ => ""
        };
        if (actionType.Length == 0) return false;
        if (actionType is "file.restore" or "file.quarantine_status")
        {
            if (!Guid.TryParse(tokens[1], out var id)) return false;
            identity = id.ToString("D"); return true;
        }
        if (tokens[1].Length != 64 || tokens[1].Any(x => !char.IsAsciiHexDigit(x))) return false;
        identity = tokens[1].ToLowerInvariant(); return true;
    }
    public static bool TryStructuredPersistenceAction(string input, out string actionType, out string identity)
    {
        actionType = ""; identity = ""; string[] tokens;
        try { tokens = Tokenize(input); } catch (EnrollmentConflictException) { return false; }
        if (tokens.Length != 2) return false;
        actionType = tokens[0].ToLowerInvariant() switch
        {
            "persistence-info" => "persistence.remediation_status",
            "remediate-persistence" => "persistence.remove",
            "service-stop" => "service.stop",
            "service-disable" => "service.disable",
            "task-disable" => "scheduled_task.disable",
            "restore-persistence" => "persistence.restore",
            _ => ""
        };
        if (actionType.Length == 0) return false;
        if (actionType == "persistence.restore")
        {
            if (!Guid.TryParse(tokens[1], out var backup)) return false;
            identity = backup.ToString("D"); return true;
        }
        if (tokens[1].Length != 64 || tokens[1].Any(x => !char.IsAsciiHexDigit(x))) return false;
        identity = tokens[1].ToLowerInvariant(); return true;
    }
    public static string Hash(string value) => Convert.ToHexString(SHA256.HashData(Encoding.UTF8.GetBytes(value))).ToLowerInvariant();
    public static string SanitizeOutput(string value)
    {
        var clean = AnsiRegex().Replace(value, "");
        return new string(clean.Select(c => char.IsControl(c) && c is not ('\r' or '\n' or '\t') ? '�' : c).ToArray());
    }
    public static string CapabilityHash(IEnumerable<string> capabilities) => Hash(string.Join('\n', capabilities.Order(StringComparer.Ordinal)));
    public static string TranscriptHash(IEnumerable<LiveTranscriptEvent> events) => Hash(string.Join('\n', events.OrderBy(x => x.OccurredAt).ThenBy(x => x.EventId).Select(x => $"{x.EventId:D}|{x.EventType}|{x.Actor}|{x.OccurredAt:O}|{x.IntegrityHash}")));
    public static string Normalize(LiveCommandType type, string input)
    {
        ValidateInput(type, input); return type == LiveCommandType.BuiltIn ? string.Join(' ', Tokenize(input)) : input.Replace("\r\n", "\n", StringComparison.Ordinal);
    }
    public static void ValidateCapabilities(string[] capabilities)
    {
        if (capabilities.Length is < 1 or > 5 || capabilities.Distinct(StringComparer.Ordinal).Count() != capabilities.Length || capabilities.Any(x => !KnownCapabilities.Contains(x, StringComparer.Ordinal))) throw new EnrollmentConflictException("LIVE_CAPABILITY_INVALID", "Live Response capability set is invalid.");
        if (!capabilities.Contains("builtin", StringComparer.Ordinal)) throw new EnrollmentConflictException("LIVE_CAPABILITY_INVALID", "Built-in capability is required.");
    }
    public static void ValidateInput(LiveCommandType type, string input)
    {
        if (string.IsNullOrWhiteSpace(input) || Encoding.UTF8.GetByteCount(input) > HardLimits.MaximumCommandBytes || input.Any(c => c == '\0' || (char.IsControl(c) && c is not ('\r' or '\n' or '\t')))) throw new EnrollmentConflictException("LIVE_COMMAND_INVALID", "Command input is empty, oversized, or contains forbidden controls.");
        if (type == LiveCommandType.BuiltIn) { var tokens = Tokenize(input); if (tokens.Length == 0 || !BuiltIns.Contains(tokens[0], StringComparer.OrdinalIgnoreCase)) throw new EnrollmentConflictException("LIVE_BUILTIN_UNKNOWN", "Built-in command is unsupported."); ValidateBuiltin(tokens); }
    }
    public static string[] Tokenize(string input)
    {
        var matches = TokenRegex().Matches(input.Trim()); var values = new List<string>(); var consumed = 0; foreach (Match m in matches) { if (m.Index != consumed && input[consumed..m.Index].Any(c => !char.IsWhiteSpace(c))) throw new EnrollmentConflictException("LIVE_BUILTIN_SYNTAX", "Built-in syntax is invalid."); values.Add(m.Groups[1].Success ? m.Groups[1].Value.Replace("\\\"", "\"", StringComparison.Ordinal) : m.Groups[2].Value); consumed = m.Index + m.Length; }
        if (consumed < input.Length && input[consumed..].Any(c => !char.IsWhiteSpace(c))) throw new EnrollmentConflictException("LIVE_BUILTIN_SYNTAX", "Built-in syntax is invalid."); return values.ToArray();
    }
    static void ValidateBuiltin(string[] t)
    {
        var name = t[0].ToLowerInvariant(); var max = name switch { "help" or "pwd" or "ps" or "services" or "connections" or "session-info" => 1, "cd" or "hash" or "stat" or "get" or "stage-tool" or "remove-tool" => 2, "ls" => 2, _ => 0 }; if (t.Length > max) throw new EnrollmentConflictException("LIVE_BUILTIN_ARGUMENTS", "Built-in arguments are invalid."); if (name is "cd" or "hash" or "stat" or "get" && t.Length != 2) throw new EnrollmentConflictException("LIVE_BUILTIN_ARGUMENTS", "A single exact path is required."); if (name is "stage-tool" or "remove-tool" && (t.Length != 2 || !Guid.TryParse(t[1], out _))) throw new EnrollmentConflictException("LIVE_TOOL_ID", "Tool staging requires one exact approved package identity."); if (t.Skip(1).Any(x => x.Contains('\0') || x.IndexOfAny(['*', '?']) >= 0)) throw new EnrollmentConflictException("LIVE_PATH_INVALID", "Wildcards and NUL are not permitted.");
    }
    public static string SessionPayload(SignedLiveSessionEnvelope e) => string.Join('\n', e.SchemaVersion, e.TenantId, e.EndpointId.ToString("D"), e.AgentId.ToString("D"), e.AgentInstallationId, e.SessionId.ToString("D"), e.AnalystId, e.CapabilityHash, e.PolicyVersion, e.IssuedAt.ToUniversalTime().ToString("O"), e.ExpiresAt.ToUniversalTime().ToString("O"), e.Nonce);
    public static string CommandPayload(SignedLiveCommandEnvelope e) => string.Join('\n', e.SchemaVersion, e.TenantId, e.EndpointId.ToString("D"), e.AgentId.ToString("D"), e.AgentInstallationId, e.SessionId.ToString("D"), e.CommandId.ToString("D"), e.AnalystId, e.CommandType, e.InputHash, e.WorkingDirectory, e.TimeoutSeconds, e.IssuedAt.ToUniversalTime().ToString("O"), e.ExpiresAt.ToUniversalTime().ToString("O"), e.Nonce, e.UploadSha256, e.Overwrite);
    public static bool Verify(SignedLiveSessionEnvelope e, string pem) => Verify(SessionPayload(e), e.Signature, e.SignatureAlgorithm, pem);
    public static bool Verify(SignedLiveCommandEnvelope e, string pem) => Hash(e.ExactInput) == e.InputHash && Verify(CommandPayload(e), e.Signature, e.SignatureAlgorithm, pem);
    static bool Verify(string payload, string signature, string algorithm, string pem) { try { using var c = System.Security.Cryptography.X509Certificates.X509Certificate2.CreateFromPem(pem); using var rsa = c.GetRSAPublicKey(); return rsa is not null && algorithm == "rsa-sha256-ca-v1" && rsa.VerifyData(Encoding.UTF8.GetBytes(payload), Convert.FromBase64String(signature), HashAlgorithmName.SHA256, RSASignaturePadding.Pkcs1); } catch (Exception x) when (x is CryptographicException or FormatException) { return false; } }
    public static bool Terminal(LiveCommandState s) => s is LiveCommandState.Succeeded or LiveCommandState.Failed or LiveCommandState.TimedOut or LiveCommandState.Cancelled or LiveCommandState.Expired or LiveCommandState.Uncertain;
    [GeneratedRegex("(?:\"((?:\\.|[^\"])*)\")|([^\\s\"]+)", RegexOptions.CultureInvariant)] private static partial Regex TokenRegex();
    [GeneratedRegex("\\x1B(?:[@-Z\\\\-_]|\\[[0-?]*[ -/]*[@-~])", RegexOptions.CultureInvariant)] private static partial Regex AnsiRegex();
}

