Guid agent, string installation, CancellationToken ct); Task<LiveSessionRecord> AuditAsync(string tenant, Guid session, Guid? command, string actor, string eventType, string summary, string integrity, IReadOnlyDictionary<string, string?> metadata, CancellationToken ct); Task SweepAsync(CancellationToken ct); Task<LiveResponseHealth> HealthAsync(string tenant, CancellationToken ct);
}

public class FileLiveResponseRepository : ILiveResponseRepository, IDisposable
{
    readonly ConcurrentDictionary<(string, Guid), LiveSessionRecord> _values = new(); readonly SemaphoreSlim _gate = new(1, 1); readonly ConcurrentDictionary<string, long[]> _metrics = new();
    protected virtual Task<IReadOnlyList<LiveSessionRecord>> LoadAsync(string tenant, CancellationToken ct) => Task.FromResult<IReadOnlyList<LiveSessionRecord>>(_values.Where(x => x.Key.Item1 == tenant).Select(x => x.Value).ToArray()); protected virtual Task<IReadOnlyList<LiveSessionRecord>> LoadAllAsync(CancellationToken ct) => Task.FromResult<IReadOnlyList<LiveSessionRecord>>(_values.Values.ToArray()); protected virtual Task PersistAsync(LiveSessionRecord value, IReadOnlyList<LiveTranscriptEvent> audit, CancellationToken ct) { _values[(value.TenantId, value.SessionId)] = value; return Task.CompletedTask; }
