    public async Task<LiveSessionRecord> CreateAsync(ResolvedLiveSessionRequest r, CancellationToken ct) { LiveResponseSafety.ValidateCapabilities(r.Input.Capabilities); if (r.Input.EndpointId != r.EndpointId || !string.Equals(r.Platform, "windows", StringComparison.OrdinalIgnoreCase)) throw new EnrollmentConflictException("LIVE_TARGET_INVALID", "Authoritative Windows endpoint binding is required."); foreach (var capability in r.Input.Capabilities) { var permission = capability switch { "builtin" => "live:execute:safe", "cmd" => "live:execute:cmd", "powershell" => "live:execute:powershell", "file-download" => "live:file:download", "file-upload" => "live:file:upload", _ => "" }; if (!r.Permissions.Contains(permission, StringComparer.Ordinal) && !r.Permissions.Contains("platform:admin", StringComparer.Ordinal)) throw new EnrollmentConflictException("LIVE_CAPABILITY_FORBIDDEN", "Requester lacks a requested capability."); } if (r.Input.PolicyVersion != "live-response-policy.v1") throw new EnrollmentConflictException("LIVE_POLICY_INVALID", "Live Response policy version is unsupported or disabled."); var l = LiveResponseSafety.HardLimits; if (r.Input.IdleTimeoutSeconds is < 60 or > 3600 || r.Input.AbsoluteLifetimeSeconds is < 300 or > 14400) throw new EnrollmentConflictException("LIVE_LIMIT_INVALID", "Session lifetime is outside hard bounds."); await _gate.WaitAsync(ct); try { var all = await LoadAsync(r.TenantId, ct); if (all.Count(x => x.AnalystId == r.AnalystId && x.State is LiveSessionState.Active or LiveSessionState.Connecting or LiveSessionState.PendingApproval) >= l.MaximumSessionsPerAnalyst || all.Count(x => x.EndpointId == r.EndpointId && x.State is LiveSessionState.Active or LiveSessionState.Connecting or LiveSessionState.PendingApproval) >= l.MaximumSessionsPerEndpoint) throw new EnrollmentConflictException("LIVE_CONCURRENCY_LIMIT", "Live Response concurrent-session limit reached."); var now = DateTimeOffset.UtcNow; var elevated = r.Input.Capabilities.Any(x => x is "cmd" or "powershell" or "file-upload"); var superAdmin = r.Permissions.Contains("platform:admin", StringComparer.Ordinal); var approvalRequired = elevated && !superAdmin; var state = approvalRequired ? LiveSessionState.PendingApproval : LiveSessionState.Connecting; var id = Guid.NewGuid(); var hash = LiveResponseSafety.CapabilityHash(r.Input.Capabilities); var s = new LiveSessionRecord("live-response-session.v1", id, r.TenantId, r.EndpointId, r.AgentId, r.AgentInstallationId, r.AnalystId, r.Permissions, r.Input.SourceAlertId, r.Input.SourceIncidentId, r.Input.SourceEntityId, r.Input.PolicyVersion, now, superAdmin && elevated ? now : null, null, now, r.Input.IdleTimeoutSeconds, now.AddSeconds(r.Input.IdleTimeoutSeconds), now.AddSeconds(r.Input.AbsoluteLifetimeSeconds), null, state, null, r.EndpointVersion, r.Platform, null, null, r.Input.Capabilities.Order(StringComparer.Ordinal).ToArray(), hash, Convert.ToHexString(RandomNumberGenerator.GetBytes(24)).ToLowerInvariant(), "", LiveResponseSafety.Hash(""), Guid.NewGuid().ToString("N"), superAdmin && elevated ? r.AnalystId : null, superAdmin && elevated ? "platform:admin direct authorization" : null, 1, [], []); var decision = approvalRequired ? "live.approval.pending" : superAdmin && elevated ? "live.approval.bypassed.super-admin" : "live.session.connecting"; var events = new[] { E(s, null, 1, "live.session.requested", r.AnalystId, "authorized session request", hash), E(s, null, 1, "live.authorization.allowed", r.AnalystId, string.Join(',', r.Input.Capabilities), hash), E(s, null, 1, decision, r.AnalystId, superAdmin && elevated ? "platform:admin" : r.Input.PolicyVersion, hash) }; s = Add(s, 1, events); await PersistAsync(s, events, ct); _metrics.GetOrAdd(r.TenantId, _ => new long[16])[0]++; return s; } finally { _gate.Release(); } }
    public async Task<LiveSessionRecord?> GetAsync(string t, Guid id, CancellationToken ct) => (await LoadAsync(t, ct)).FirstOrDefault(x => x.SessionId == id); public async Task<IReadOnlyList<LiveSessionRecord>> ListAsync(string t, Guid? endpoint, CancellationToken ct) => (await LoadAsync(t, ct)).Where(x => endpoint is null || x.EndpointId == endpoint).OrderByDescending(x => x.CreatedAt).Take(200).ToArray();
    public async Task<LiveSessionRecord> ApproveAsync(string t, Guid id, string actor, LiveApprovalRequest input, CancellationToken ct) { await _gate.WaitAsync(ct); try { var s = await GetAsync(t, id, ct) ?? throw new KeyNotFoundException(); var superAdminSelfAuthorization = actor == s.AnalystId && s.RequesterPermissions.Contains("platform:admin", StringComparer.Ordinal); if (s.State != LiveSessionState.PendingApproval || actor == s.AnalystId && !superAdminSelfAuthorization || !CryptographicOperations.FixedTimeEquals(Encoding.ASCII.GetBytes(s.CapabilityHash), Encoding.ASCII.GetBytes(input.CapabilityHash))) throw new EnrollmentConflictException("LIVE_APPROVAL_INVALID", "Approval actor, state, or exact capability hash is invalid."); var eventType = superAdminSelfAuthorization ? "live.approval.bypassed.super-admin" : "live.session.approved"; var e = E(s, null, s.Version + 1, eventType, actor, input.Reason, s.CapabilityHash); s = Add(s with { State = LiveSessionState.Connecting, ApprovedAt = DateTimeOffset.UtcNow, ApproverId = actor, ApprovalReason = input.Reason }, s.Version + 1, e); await PersistAsync(s, [e], ct); return s; } finally { _gate.Release(); } }
